(1850803, 255394, 24212, '<td valign="top">I was at first going to suggest some additional sharpening, but after looking at this for a while, I find that it looks OK as it is as well. I think that the colours are well done.</td>', 'I was at first going to suggest some additional sharpening, but after looking at this for a while, I find that it looks OK as it is as well. I think that the colours are well done.', '2005-11-09 12:14:51.000000', NULL, 1),
(1850806, 254673, 24212, '<td valign="top">To me, the lighting looks a little harsh, which mars the effect that could be obtained here.</td>', 'To me, the lighting looks a little harsh, which mars the effect that could be obtained here.', '2005-11-09 12:16:08.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1850810, 255208, 24212, '<td valign="top">I like the idea, although the lighting is a little too harsh perhaps.</td>', 'I like the idea, although the lighting is a little too harsh perhaps.', '2005-11-09 12:17:11.000000', NULL, 1),
(1850816, 255228, 24212, '<td valign="top">I quite like the lighting here. It really makes this look like a forgotten corner.</td>', 'I quite like the lighting here. It really makes this look like a forgotten corner.', '2005-11-09 12:18:44.000000', NULL, 1),
(1850819, 255528, 24212, '<td valign="top">A pity about this being an open challenge, the couple of blotches on the disk spoil the simplicity a bit.</td>', 'A pity about this being an open challenge, the couple of blotches on the disk spoil the simplicity a bit.', '2005-11-09 12:19:52.000000', NULL, 1),
(1850823, 254677, 24212, '<td valign="top">This really makes me wonder what''s around the corner.</td>', 'This really makes me wonder what''s around the corner.', '2005-11-09 12:20:29.000000', NULL, 1),
(1850825, 255276, 24212, '<td valign="top">To me, the focus is in the right part of the frame, as that''s where my eye is first drawn to and where it keeps coming back to.</td>', 'To me, the focus is in the right part of the frame, as that''s where my eye is first drawn to and where it keeps coming back to.', '2005-11-09 12:21:33.000000', NULL, 1),
(1850826, 254797, 24212, '<td valign="top">I feel that the post in the bottom right of the frame intrudes somewhat.</td>', 'I feel that the post in the bottom right of the frame intrudes somewhat.', '2005-11-09 12:22:16.000000', NULL, 1),
(1850830, 254610, 24212, '<td valign="top">I feel that a little more sharpening would really bring out those textures.</td>', 'I feel that a little more sharpening would really bring out those textures.', '2005-11-09 12:23:25.000000', NULL, 1),
(1850840, 254819, 24212, '<td valign="top">Clever idea and very good lighting, although the centre portion of the can looks perhaps a little too dark and overpowers the rest.</td>', 'Clever idea and very good lighting, although the centre portion of the can looks perhaps a little too dark and overpowers the rest.', '2005-11-09 12:26:22.000000', NULL, 1),
(1850849, 254164, 24212, '<td valign="top">I''d like to see this with really tight DOF around the area just in front of the packets.</td>', 'I''d like to see this with really tight DOF around the area just in front of the packets.', '2005-11-09 12:28:51.000000', NULL, 1),
(1850858, 253710, 24212, '<td valign="top">I bet plenty of people have asked why this is so small. Is this a figurative thing or a slip-up?</td>', 'I bet plenty of people have asked why this is so small. Is this a figurative thing or a slip-up?', '2005-11-09 12:30:25.000000', NULL, 1),
(1850867, 255532, 24212, '<td valign="top">I cant help feeling that the OOF wrapper in the lower left dominates a little too much. Great splash of colour, though.</td>', 'I cant help feeling that the OOF wrapper in the lower left dominates a little too much. Great splash of colour, though.', '2005-11-09 12:31:28.000000', NULL, 1),
(1850869, 255303, 24212, '<td valign="top">Very bleak. A great reminder.</td>', 'Very bleak. A great reminder.', '2005-11-09 12:31:46.000000', NULL, 1),
(1850871, 254902, 29906, '<td valign="top">Wow, this is very creative .. Higher contrast could improve the overall appeal of this photo in my opinion</td>', 'Wow, this is very creative .. Higher contrast could improve the overall appeal of this photo in my opinion', '2005-11-09 12:32:03.000000', NULL, 1),
(1850874, 255226, 24212, '<td valign="top">Is that an Allegro in there? If so, it deserves to be thrown away. Great selection of colours and I feel that the grain works well also.</td>', 'Is that an Allegro in there? If so, it deserves to be thrown away. Great selection of colours and I feel that the grain works well also.', '2005-11-09 12:32:55.000000', NULL, 1),
(1850877, 255465, 1881, '<td valign="top">I like this one. This really gives the feel of the race, and the clean up.... I think this is well composed and well lit.</td>', 'I like this one. This really gives the feel of the race, and the clean up.... I think this is well composed and well lit.', '2005-11-09 12:33:30.000000', NULL, 1),
(1850878, 252555, 24212, '<td valign="top">Great clarity and sharpness. A pity about the pole behind the man.</td>', 'Great clarity and sharpness. A pity about the pole behind the man.', '2005-11-09 12:33:34.000000', NULL, 1),
(1850881, 255422, 24212, '<td valign="top">Very bleak indeed.</td>', 'Very bleak indeed.', '2005-11-09 12:33:59.000000', NULL, 1),
(1850891, 255214, 24212, '<td valign="top">A good idea, although perhaps there could be a little crop from the right hand side and the bottom to improve emphasis slightly.</td>', 'A good idea, although perhaps there could be a little crop from the right hand side and the bottom to improve emphasis slightly.', '2005-11-09 12:35:55.000000', NULL, 1),
(1850900, 254533, 24212, '<td valign="top">This doesn''t really yell ''garbage'' at me, but I like the composition and DOF.</td>', 'This doesn''t really yell ''garbage'' at me, but I like the composition and DOF.', '2005-11-09 12:37:01.000000', NULL, 1),
(1850905, 253710, 35602, '<td valign="top">I am sure you have already been told that the image did not fill the frame.  Beyond that, it was badly focused, and you should try to remove the date which appears in the lower left before submitting.  These are all things that can be remedied as you take more pictures.  The mistakes will become less and less, then you have to deal with things like composition, subject attractiveness, and all those variables which people vote on.</td>', 'I am sure you have already been told that the image did not fill the frame.  Beyond that, it was badly focused, and you should try to remove the date which appears in the lower left before submitting.  These are all things that can be remedied as you take more pictures.  The mistakes will become less and less, then you have to deal with things like composition, subject attractiveness, and all those variables which people vote on.', '2005-11-09 12:37:54.000000', NULL, 1),
(1850906, 255519, 24212, '<td valign="top">A great angle chosen and really strong lines created. I like the subtle colours, too.</td>', 'A great angle chosen and really strong lines created. I like the subtle colours, too.', '2005-11-09 12:38:01.000000', NULL, 1),
(1850909, 255309, 35602, '<td valign="top">Beautiful background.  I think that the film was added just to meet the challenge.  I hope you have this image without the film canister.  That really wrecked it for me.</td>', 'Beautiful background.  I think that the film was added just to meet the challenge.  I hope you have this image without the film canister.  That really wrecked it for me.', '2005-11-09 12:39:05.000000', NULL, 1),
(1850910, 255490, 24212, '<td valign="top">I like the way that you''ve retained enough detail in the wastebasket to convey its outline and the sense of movement in the falling cans.</td>', 'I like the way that you''ve retained enough detail in the wastebasket to convey its outline and the sense of movement in the falling cans.', '2005-11-09 12:39:13.000000', NULL, 1),
(1850920, 253365, 35602, '<td valign="top">The balloon didn''t take up enough of the image.  It also doesn''t look like a balloon.   Compositionally, you set the frame very nicely.  It does appear a little too dark, though.  As to the best composition, since the challenge was garbage, you need to show that better in your image.  A nice cropping to leave the balloon and part of the wave would have been better.  If that was too out of focus when enlarged, a shot or two at a closer vantage point would have given you a better choice of which image would have worked best.</td>', 'The balloon didn''t take up enough of the image.  It also doesn''t look like a balloon.   Compositionally, you set the frame very nicely.  It does appear a little too dark, though.  As to the best composition, since the challenge was garbage, you need to show that better in your image.  A nice cropping to leave the balloon and part of the wave would have been better.  If that was too out of focus when enlarged, a shot or two at a closer vantage point would have given you a better choice of which image would have worked best.', '2005-11-09 12:42:24.000000', NULL, 1),
(1850923, 255196, 24212, '<td valign="top">A good shot of this rat (or is it a mouse?). Perhaps a little more sharpening and a slightly tighter crop.</td>', 'A good shot of this rat (or is it a mouse?). Perhaps a little more sharpening and a slightly tighter crop.', '2005-11-09 12:42:50.000000', NULL, 1),
(1850930, 254988, 24212, '<td valign="top">I like the splash of colour against the grey background of the paving.</td>', 'I like the splash of colour against the grey background of the paving.', '2005-11-09 12:43:44.000000', NULL, 1),
(1850932, 253320, 24212, '<td valign="top">Great detail in the in-focus parts and wonderful DOF.</td>', 'Great detail in the in-focus parts and wonderful DOF.', '2005-11-09 12:44:27.000000', NULL, 1),
(1850986, 254938, 45790, '<td valign="top">Foreground candy(?) not in focus.</td>', 'Foreground candy(?) not in focus.', '2005-11-09 12:59:19.000000', NULL, 1),
(1850990, 255349, 45790, '<td valign="top">So they corked it before tossing it? Looks too contrived.</td>', 'So they corked it before tossing it? Looks too contrived.', '2005-11-09 13:01:04.000000', NULL, 1),
(1850995, 255161, 45790, '<td valign="top">Good color. Motion blur tells story well.</td>', 'Good color. Motion blur tells story well.', '2005-11-09 13:02:16.000000', NULL, 1),
(1850999, 254617, 30605, '<td valign="top">I really like to monochromatic tone in this picture. Good use of selective desaturation. Good compisition with reflexion and all. 8</td>', 'I really like to monochromatic tone in this picture. Good use of selective desaturation. Good compisition with reflexion and all. 8', '2005-11-09 13:03:13.000000', NULL, 1),
(1851004, 255453, 30605, '<td valign="top">Very nice picture that tells a story. Interesting leading line and good use of shallow depth of field.</td>', 'Very nice picture that tells a story. Interesting leading line and good use of shallow depth of field.', '2005-11-09 13:04:39.000000', NULL, 1),
(1851011, 253637, 30605, '<td valign="top">Very good use of low angle shot and shallow depth of field. Really good focus that catch the eyes.</td>', 'Very good use of low angle shot and shallow depth of field. Really good focus that catch the eyes.', '2005-11-09 13:06:10.000000', NULL, 1),
(1851012, 255314, 45790, '<td valign="top">In general, I like this. But I''m bothered by the centered "target" on the farm equipment. Is this a figurative "bulls eye" photo?</td>', 'In general, I like this. But I''m bothered by the centered "target" on the farm equipment. Is this a figurative "bulls eye" photo?', '2005-11-09 13:06:15.000000', NULL, 1),
(1851023, 255596, 45790, '<td valign="top">The burned structure meets the topic, but the building would be interesting even without the trash. Good shot!</td>', 'The burned structure meets the topic, but the building would be interesting even without the trash. Good shot!', '2005-11-09 13:08:19.000000', NULL, 1),
(1851028, 254218, 45790, '<td valign="top">Sorry. Blown sky. Uninteresting garbage.</td>', 'Sorry. Blown sky. Uninteresting garbage.', '2005-11-09 13:09:07.000000', NULL, 1),
(1851031, 255207, 46177, '<td valign="top">You should have titled this "How to make garbage look like art"</td>', 'You should have titled this "How to make garbage look like art"', '2005-11-09 13:10:15.000000', NULL, 1),
(1851037, 253346, 30605, '<td valign="top">Very powerfull story here. Composition is great. I especially like the bullet hole in the helmet; frightening.<br/>It would have been more powerfull if the sun wasn''t shinning in the background; it kind of add some warmth that doesn''t serve the purpose here. Another angle or an overcast day would have made this picture perfect.</td>', 'Very powerfull story here. Composition is great. I especially like the bullet hole in the helmet; frightening.It would have been more powerfull if the sun wasn''t shinning in the background; it kind of add some warmth that doesn''t serve the purpose here. Another angle or an overcast day would have made this picture perfect.', '2005-11-09 13:11:40.000000', NULL, 1),
(1851039, 255448, 45790, '<td valign="top">Yeah, yeah. Cheap shot. I like Whoppers! But I can''t dismiss the photo which has lots of "trashy" detail like the posters and grafitti as well as the trash bins.</td>', 'Yeah, yeah. Cheap shot. I like Whoppers! But I can''t dismiss the photo which has lots of "trashy" detail like the posters and grafitti as well as the trash bins.', '2005-11-09 13:12:04.000000', NULL, 1),
(1851048, 254010, 9111, '<td valign="top">this is not garbage</td>', 'this is not garbage', '2005-11-09 13:15:22.000000', NULL, 1),
(1851050, 253637, 46045, '<td valign="top">lol   love it.</td>', 'lol   love it.', '2005-11-09 13:16:47.000000', NULL, 1),
(1851060, 253314, 46177, '<td valign="top">This has met the challenge perfectly and in a moving way, well done. 10</td>', 'This has met the challenge perfectly and in a moving way, well done. 10', '2005-11-09 13:20:33.000000', NULL, 1),
(1851065, 255296, 46177, '<td valign="top">I really like the use of the selective desat, works really well here.  The green is the focal point but still subtle.</td>', 'I really like the use of the selective desat, works really well here.  The green is the focal point but still subtle.', '2005-11-09 13:21:43.000000', NULL, 1),
(1851066, 254956, 45790, '<td valign="top">Oversaturation does nothing for this.</td>', 'Oversaturation does nothing for this.', '2005-11-09 13:22:33.000000', NULL, 1),
(1851069, 255226, 46177, '<td valign="top">The grain adds to the shot, makes it moody, hope you do well yours is one of my favorites. 10</td>', 'The grain adds to the shot, makes it moody, hope you do well yours is one of my favorites. 10', '2005-11-09 13:23:01.000000', NULL, 1),
(1851072, 254234, 45790, '<td valign="top">Good photo which I expect many will find too subdued, but not me.</td>', 'Good photo which I expect many will find too subdued, but not me.', '2005-11-09 13:24:00.000000', NULL, 1),
(1851080, 254957, 46177, '<td valign="top">"Sushi" Thats what I was planning on having for lunch!  Well maybe tomorrow, very well done !)</td>', '"Sushi" Thats what I was planning on having for lunch!  Well maybe tomorrow, very well done !)', '2005-11-09 13:25:40.000000', NULL, 1),
(1851081, 253420, 46177, '<td valign="top">Cant think of any critism for this shot, its simply a good one!  10</td>', 'Cant think of any critism for this shot, its simply a good one!  10', '2005-11-09 13:25:54.000000', NULL, 1),
(1851082, 254016, 45790, '<td valign="top">Suffed animal, soft focus, glare, bad exposure. I don''t know what I''m seeing.<br/></td>', 'Suffed animal, soft focus, glare, bad exposure. I don''t know what I''m seeing.', '2005-11-09 13:26:15.000000', NULL, 1),
(1851084, 255157, 46177, '<td valign="top">The crop works really well here, the colours and angle give this little car a personality, I really like this shot. 9</td>', 'The crop works really well here, the colours and angle give this little car a personality, I really like this shot. 9', '2005-11-09 13:27:28.000000', NULL, 1),
(1851087, 255441, 46177, '<td valign="top">Well done still life that meets this challenge.</td>', 'Well done still life that meets this challenge.', '2005-11-09 13:27:57.000000', NULL, 1),
(1851093, 255490, 46177, '<td valign="top">Like the use of the empty space and the colour white, reall brings your attention to the red in the cans,</td>', 'Like the use of the empty space and the colour white, reall brings your attention to the red in the cans,', '2005-11-09 13:28:49.000000', NULL, 1),
(1851096, 253320, 40464, '<td valign="top">Love the noise and DOF</td>', 'Love the noise and DOF', '2005-11-09 13:29:05.000000', NULL, 1),
(1851098, 255196, 46177, '<td valign="top">Good and original idea. 9</td>', 'Good and original idea. 9', '2005-11-09 13:29:45.000000', NULL, 1),
(1851099, 255241, 40464, '<td valign="top">To much of a snapshot in here...</td>', 'To much of a snapshot in here...', '2005-11-09 13:29:56.000000', NULL, 1),
(1851111, 252943, 46177, '<td valign="top">I think this would have been better if it had been cropped with a little more room on the sides not cutting off the bags, also its too  bad the bags were not the darker green or black the shot just lacks a focal point either through colour or composition. I am also not quite sure what the title means.</td>', 'I think this would have been better if it had been cropped with a little more room on the sides not cutting off the bags, also its too  bad the bags were not the darker green or black the shot just lacks a focal point either through colour or composition. I am also not quite sure what the title means.', '2005-11-09 13:32:31.000000', NULL, 1),
(1851121, 254010, 46177, '<td valign="top">I am not sure what you are really getting at here, did you mean society considers her rot?  If so I think the shot missed that a little, perhaps she is just not trashy looking enough, (yes even in that outfit)  Still I do really like the colour in the photo</td>', 'I am not sure what you are really getting at here, did you mean society considers her rot?  If so I think the shot missed that a little, perhaps she is just not trashy looking enough, (yes even in that outfit)  Still I do really like the colour in the photo', '2005-11-09 13:34:30.000000', NULL, 1),
(1851125, 255043, 40464, '<td valign="top">Nice composition nad colour... usually I bark on those who submit photos with drunk horizon, but here it looks quite good. 8</td>', 'Nice composition nad colour... usually I bark on those who submit photos with drunk horizon, but here it looks quite good. 8', '2005-11-09 13:35:49.000000', NULL, 1),
(1851130, 253710, 46177, '<td valign="top">I am not sure you got your message accross, we all know smoking is bad but where in your shot does it express garbage?  It can''t be in the beautiful leaves in the background.  Anyway sorry I don''t feel it meets the challenge. 4</td>', 'I am not sure you got your message accross, we all know smoking is bad but where in your shot does it express garbage?  It can''t be in the beautiful leaves in the background.  Anyway sorry I don''t feel it meets the challenge. 4', '2005-11-09 13:36:19.000000', NULL, 1),
(1851131, 254010, 45790, '<td valign="top">Photo is technically fine, especially considering the lighting. But I don''t like the title or the stereotyping. This might just be "youthful rebellion" or "staged photo" for that matter.</td>', 'Photo is technically fine, especially considering the lighting. But I don''t like the title or the stereotyping. This might just be "youthful rebellion" or "staged photo" for that matter.', '2005-11-09 13:36:22.000000', NULL, 1),
(1851135, 255590, 46177, '<td valign="top">Cute little boy however I am not sure how he relates to garbage, also he is very out of focus.  In my opinion your missed the challenge. 3</td>', 'Cute little boy however I am not sure how he relates to garbage, also he is very out of focus.  In my opinion your missed the challenge. 3', '2005-11-09 13:37:24.000000', NULL, 1),
(1851137, 255416, 45790, '<td valign="top">Caught it! Good framing, exposure and color.</td>', 'Caught it! Good framing, exposure and color.', '2005-11-09 13:37:29.000000', NULL, 1),
(1851139, 255179, 3102, '<td valign="top">Hey... that''s an Ikea garbage can, isn''t it?  I have an identical one in my computer room.  I remember buying it right after the last Garbage challenge!  I like the shot a lot, by the way... :)  - 9</td>', 'Hey... that''s an Ikea garbage can, isn''t it?  I have an identical one in my computer room.  I remember buying it right after the last Garbage challenge!  I like the shot a lot, by the way... :)  - 9', '2005-11-09 13:37:56.000000', NULL, 1),
(1851141, 254609, 45790, '<td valign="top">That trash could be somebodys treasure.</td>', 'That trash could be somebodys treasure.', '2005-11-09 13:38:19.000000', NULL, 1),
(1851158, 255590, 41370, '<td valign="top">I know that many of these challenges are open to the photographers interpretation but I can''t stretch my imagination far enough to place a child in the garbage challenge.</td>', 'I know that many of these challenges are open to the photographers interpretation but I can''t stretch my imagination far enough to place a child in the garbage challenge.', '2005-11-09 13:42:59.000000', NULL, 1),
(1851160, 253660, 46177, '<td valign="top">This picture is nice enough but easily passed over here.  It does not have any impact when opened up.  The cork is nicely in focus and your depth of field in my opinion is good.  It is just not a pleasing image,  for me part of that is the colours, the gold and the wood don''t really compliment each other well and nothing in particular really stands out here. In my opinion only there needs to be more of a reason for looking at a picture. I hope this helps its only one opinion. 5</td>', 'This picture is nice enough but easily passed over here.  It does not have any impact when opened up.  The cork is nicely in focus and your depth of field in my opinion is good.  It is just not a pleasing image,  for me part of that is the colours, the gold and the wood don''t really compliment each other well and nothing in particular really stands out here. In my opinion only there needs to be more of a reason for looking at a picture. I hope this helps its only one opinion. 5', '2005-11-09 13:43:16.000000', NULL, 1),
(1851169, 255037, 42170, '<td valign="top">Refreshing! <br/>Well done!</td>', 'Refreshing! Well done!', '2005-11-09 13:46:00.000000', NULL, 1),
(1851171, 255210, 41370, '<td valign="top">Check with OJ!!</td>', 'Check with OJ!!', '2005-11-09 13:46:05.000000', NULL, 1),
(1851174, 253016, 46177, '<td valign="top">Cute idea however it does not have much of an impact when looked at, maybe the heart should have been the focal point as it is more colourful on the black background or maybe you could have cropped it differently so the garbage can was more the focal point as it is I am not sure what I am looking at first, the hand, heart or garbage can.  Still I do think this looks good on the plain black background and the large white frame also helps to bring it out. 5</td>', 'Cute idea however it does not have much of an impact when looked at, maybe the heart should have been the focal point as it is more colourful on the black background or maybe you could have cropped it differently so the garbage can was more the focal point as it is I am not sure what I am looking at first, the hand, heart or garbage can.  Still I do think this looks good on the plain black background and the large white frame also helps to bring it out. 5', '2005-11-09 13:46:37.000000', NULL, 1),
(1851179, 255480, 3102, '<td valign="top">This shot feels eerily familiar!  :)</td>', 'This shot feels eerily familiar!  :)', '2005-11-09 13:47:19.000000', NULL, 1),
(1851180, 254004, 40464, '<td valign="top">Maybe it would look better if the sun was behind the trash, this way I look more at the sun than trash... still in better half of submited photos...</td>', 'Maybe it would look better if the sun was behind the trash, this way I look more at the sun than trash... still in better half of submited photos...', '2005-11-09 13:47:24.000000', NULL, 1),
(1851198, 255518, 46177, '<td valign="top">This picture is a little dark for my taste, not quite a silhouette but not quite there either, also I am not sure I believe you meet the challenge,  Not sure if he is suppose to be the garbage?? 5</td>', 'This picture is a little dark for my taste, not quite a silhouette but not quite there either, also I am not sure I believe you meet the challenge,  Not sure if he is suppose to be the garbage?? 5', '2005-11-09 13:50:42.000000', NULL, 1),
(1851204, 253320, 17446, '<td valign="top">Nice photo.  Interesting subject.  Good dof.  Nice tones.  The only room I see for improvement is it''s relation to "garbage."  Not bad.</td>', 'Nice photo.  Interesting subject.  Good dof.  Nice tones.  The only room I see for improvement is it''s relation to "garbage."  Not bad.', '2005-11-09 13:51:56.000000', NULL, 1),
(1851207, 255532, 17446, '<td valign="top">This is one of the better candy wrapper photos in this challenge.  The crazy loud border works with the crazy loud trash.  Good job.</td>', 'This is one of the better candy wrapper photos in this challenge.  The crazy loud border works with the crazy loud trash.  Good job.', '2005-11-09 13:52:52.000000', NULL, 1),
(1851208, 253574, 3102, '<td valign="top">Having done this sort of shot before, I know how much effort goes into pulling it off!  I like the way you made it look like a monster-sized apple :)</td>', 'Having done this sort of shot before, I know how much effort goes into pulling it off!  I like the way you made it look like a monster-sized apple :)', '2005-11-09 13:52:58.000000', NULL, 1),
(1851212, 253764, 46177, '<td valign="top">While this picture does meet the challenge it has nothing of real interest in it, maybe its the way its all centred, the road runs almost down the middle and the garbage can is in the middle of that.  The can is green and the lawn is green the rest is grayish black, I wish something stood out more or there was more interest to make me want to look at this photo as it is its quite easy to just pass this one by.</td>', 'While this picture does meet the challenge it has nothing of real interest in it, maybe its the way its all centred, the road runs almost down the middle and the garbage can is in the middle of that.  The can is green and the lawn is green the rest is grayish black, I wish something stood out more or there was more interest to make me want to look at this photo as it is its quite easy to just pass this one by.', '2005-11-09 13:54:03.000000', NULL, 1),
(1851214, 252813, 17446, '<td valign="top">Alright, good abstract.  I''ll vote this higher than most voters I''m sure.  Good job.</td>', 'Alright, good abstract.  I''ll vote this higher than most voters I''m sure.  Good job.', '2005-11-09 13:54:57.000000', NULL, 1),
(1851218, 255465, 18552, '<td valign="top">I really like your picture! It is nice that it shows garbage without having to be grainy or depressing. The lighting and composition is really excellent.</td>', 'I really like your picture! It is nice that it shows garbage without having to be grainy or depressing. The lighting and composition is really excellent.', '2005-11-09 13:55:28.000000', NULL, 1),
(1851224, 255449, 18552, '<td valign="top">Very nice picture. The subdued lighting really suits it. It is so nice to see a garbage picture that does show trash but is also lovely to look at. Great Job.</td>', 'Very nice picture. The subdued lighting really suits it. It is so nice to see a garbage picture that does show trash but is also lovely to look at. Great Job.', '2005-11-09 13:56:43.000000', NULL, 1),
