INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1851696, 255465, 32644, '<td valign="top">What a mess. Good thing they have volunteers to clean it up. Excellent catch.</td>', 'What a mess. Good thing they have volunteers to clean it up. Excellent catch.', '2005-11-09 15:42:44.000000', NULL, 1),
(1851698, 253637, 32644, '<td valign="top">Funny! Good set-up and DOF.</td>', 'Funny! Good set-up and DOF.', '2005-11-09 15:43:30.000000', NULL, 1),
(1851703, 254496, 32644, '<td valign="top">Eeeuuuwww. After what? This is very yucky - I love it. All the textures around the moldy cups make this shot!</td>', 'Eeeuuuwww. After what? This is very yucky - I love it. All the textures around the moldy cups make this shot!', '2005-11-09 15:44:52.000000', NULL, 1),
(1851709, 255268, 32644, '<td valign="top">I like this shot. The rat looks drugged or sleepy. Hmmmm...</td>', 'I like this shot. The rat looks drugged or sleepy. Hmmmm...', '2005-11-09 15:46:07.000000', NULL, 1),
(1851715, 254904, 32644, '<td valign="top">Wow. Very scary shot. The reflection in the drop is cool!</td>', 'Wow. Very scary shot. The reflection in the drop is cool!', '2005-11-09 15:46:59.000000', NULL, 1),
(1851719, 255114, 32644, '<td valign="top">What a fun catch! Perfect DOF. Puts a different slant on Dumpster Diving.</td>', 'What a fun catch! Perfect DOF. Puts a different slant on Dumpster Diving.', '2005-11-09 15:48:00.000000', NULL, 1),
(1851723, 255485, 45790, '<td valign="top">The appearance of the lower left of the Hershey label is strange. perhaps the lighting is too harsh or it has been very oversharpened. Also needs more DOF -- wrapper in foreground, bottom-right is out of focus. Perhaps image was oversharpened to attempt to make up for focus?</td>', 'The appearance of the lower left of the Hershey label is strange. perhaps the lighting is too harsh or it has been very oversharpened. Also needs more DOF -- wrapper in foreground, bottom-right is out of focus. Perhaps image was oversharpened to attempt to make up for focus?', '2005-11-09 15:48:08.000000', NULL, 1),
(1851727, 254619, 32644, '<td valign="top">I love your shoes! I also like what you have done with this shot.</td>', 'I love your shoes! I also like what you have done with this shot.', '2005-11-09 15:49:17.000000', NULL, 1),
(1851731, 255309, 45790, '<td valign="top">Too classy looking for topic. If this is a disparaging remark about the film, why is it in such a nice setting?</td>', 'Too classy looking for topic. If this is a disparaging remark about the film, why is it in such a nice setting?', '2005-11-09 15:50:12.000000', NULL, 1),
(1851734, 254617, 33652, '<td valign="top">beautiful!</td>', 'beautiful!', '2005-11-09 15:50:54.000000', NULL, 1),
(1851735, 254843, 45790, '<td valign="top">Yep. Trash in a trashy container on a trashy street. Certainly meets the topic!  Also a good photograph.</td>', 'Yep. Trash in a trashy container on a trashy street. Certainly meets the topic!  Also a good photograph.', '2005-11-09 15:51:18.000000', NULL, 1),
(1851736, 254164, 32644, '<td valign="top">If you do this with every challenge, you may not live to see the results. Still - Great setup. LOL</td>', 'If you do this with every challenge, you may not live to see the results. Still - Great setup. LOL', '2005-11-09 15:51:24.000000', NULL, 1),
(1851740, 255537, 32644, '<td valign="top">What a beautiful street. Good setting for garbage. Good luck.</td>', 'What a beautiful street. Good setting for garbage. Good luck.', '2005-11-09 15:52:19.000000', NULL, 1),
(1851745, 255592, 45790, '<td valign="top">Photograph is too busy.Maybe if it were just the potted plant and "water me please", it would get the point across without distraction.<br/> <br/></td>', 'Photograph is too busy.Maybe if it were just the potted plant and "water me please", it would get the point across without distraction. ', '2005-11-09 15:53:43.000000', NULL, 1),
