(1852914, 255480, 46177, '<td valign="top">Gargage in motion!  Great shot, black and white gives it so much impact.</td>', 'Gargage in motion!  Great shot, black and white gives it so much impact.', '2005-11-09 21:40:32.000000', NULL, 1),
(1852925, 255106, 45790, '<td valign="top">I like this. Hope this isn''t a public garden -- the drainpipe is *really* ugly, more so than the trash.</td>', 'I like this. Hope this isn''t a public garden -- the drainpipe is *really* ugly, more so than the trash.', '2005-11-09 21:43:44.000000', NULL, 1),
(1852930, 255606, 45790, '<td valign="top">Nicely done.</td>', 'Nicely done.', '2005-11-09 21:44:46.000000', NULL, 1),
(1852933, 253346, 46177, '<td valign="top">Very interesting and unique phot, the subtle colours bring out the interest of the natural pattern of the helmuts and makes me take extra time looking at this picture, very subtle and very pleasing to me.  Good luck hope you do well in this challenge.</td>', 'Very interesting and unique phot, the subtle colours bring out the interest of the natural pattern of the helmuts and makes me take extra time looking at this picture, very subtle and very pleasing to me.  Good luck hope you do well in this challenge.', '2005-11-09 21:45:24.000000', NULL, 1),
