(1852937, 255453, 46177, '<td valign="top">This is a very simple and pleasing shot, sometimes simplicity can be very thought provoking and in my opinion you have acheived that.</td>', 'This is a very simple and pleasing shot, sometimes simplicity can be very thought provoking and in my opinion you have acheived that.', '2005-11-09 21:46:42.000000', NULL, 1),
(1852938, 255179, 46177, '<td valign="top">I like the set up and the crispness of the colours in this photo, very nicely done in my opinion.</td>', 'I like the set up and the crispness of the colours in this photo, very nicely done in my opinion.', '2005-11-09 21:47:40.000000', NULL, 1),
