(1853171, 254633, 42100, '<td valign="top">Very nice photo, I like the contrasts between the silver of metal and the orange.  "Toxic" would also work well as a title for this photo.  Good luck!</td>', 'Very nice photo, I like the contrasts between the silver of metal and the orange.  "Toxic" would also work well as a title for this photo.  Good luck!', '2005-11-09 22:51:35.000000', NULL, 1),
(1853190, 253420, 42100, '<td valign="top">I don''t know where to start, everthing is great about this photo.  I''d have to say I like the contrast and composition of this photo best.  It has very good tone and mood also.</td>', 'I don''t know where to start, everthing is great about this photo.  I''d have to say I like the contrast and composition of this photo best.  It has very good tone and mood also.', '2005-11-09 22:53:33.000000', NULL, 1),
(1853197, 255490, 42100, '<td valign="top">Very well composed.  The bright red of the coke can is great against the bright white of the background.  Very well done!</td>', 'Very well composed.  The bright red of the coke can is great against the bright white of the background.  Very well done!', '2005-11-09 22:54:50.000000', NULL, 1),
(1853201, 254108, 42100, '<td valign="top">Good work.  I love the flow curve and flow of this photo.  The lighting is perfect.</td>', 'Good work.  I love the flow curve and flow of this photo.  The lighting is perfect.', '2005-11-09 22:56:04.000000', NULL, 1),
(1853219, 253229, 42100, '<td valign="top">Great photo, very bright and cheerful.  Doesn''t look at all like garbage at all.</td>', 'Great photo, very bright and cheerful.  Doesn''t look at all like garbage at all.', '2005-11-09 22:58:39.000000', NULL, 1),
