(1853344, 255296, 47365, '<td valign="top">assuming this was done with no region selections, congratulations!  a great picture.</td>', 'assuming this was done with no region selections, congratulations!  a great picture.', '2005-11-09 23:28:58.000000', NULL, 1),
(1853351, 255214, 47365, '<td valign="top">the image looks a little grainy, and it feels a bit off-balance to me.  i like the setup though.</td>', 'the image looks a little grainy, and it feels a bit off-balance to me.  i like the setup though.', '2005-11-09 23:29:44.000000', NULL, 1),
