(1855299, 255525, 24212, '<td valign="top">Grat concept and great setup. Lighting isn''t bad, either.</td>', 'Grat concept and great setup. Lighting isn''t bad, either.', '2005-11-10 15:21:57.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1855307, 254254, 24212, '<td valign="top">The tight DOF really makes this shot. The bright colours work well, too.</td>', 'The tight DOF really makes this shot. The bright colours work well, too.', '2005-11-10 15:23:25.000000', NULL, 1),
(1855520, 254399, 36060, '<td valign="top">Sorry, I don´t see any garbage.</td>', 'Sorry, I don´t see any garbage.', '2005-11-10 16:03:30.000000', NULL, 1),
(1855523, 255490, 36060, '<td valign="top">Well done.</td>', 'Well done.', '2005-11-10 16:04:27.000000', NULL, 1),
(1855527, 254617, 36060, '<td valign="top">I like this shot, it has very good lighting and it is well composed.</td>', 'I like this shot, it has very good lighting and it is well composed.', '2005-11-10 16:06:04.000000', NULL, 1),
(1855542, 253346, 41531, '<td valign="top">thought provoking and certainly captures ones attention.</td>', 'thought provoking and certainly captures ones attention.', '2005-11-10 16:12:34.000000', NULL, 1),
(1855623, 255034, 39850, '<td valign="top">8 - Good and creative.  Criticism; perhaps a ''tidy up'' ofthe coffee grains(?), not sure, might look too ''aesthetic'' cleaned up though.  Just needs a little ''something'' to add a dramatic effect in my opinion, but no idea how or where, maybe lighting, background, not sure.</td>', '8 - Good and creative.  Criticism; perhaps a ''tidy up'' ofthe coffee grains(?), not sure, might look too ''aesthetic'' cleaned up though.  Just needs a little ''something'' to add a dramatic effect in my opinion, but no idea how or where, maybe lighting, background, not sure.', '2005-11-10 16:30:26.000000', NULL, 1),
(1855628, 253651, 39850, '<td valign="top">7 - Good perspective.  Criticism; would like to have seen the ''focal point'' on the garbage more so and the garbage incorporated more into the frame, ''somehow''.</td>', '7 - Good perspective.  Criticism; would like to have seen the ''focal point'' on the garbage more so and the garbage incorporated more into the frame, ''somehow''.', '2005-11-10 16:31:29.000000', NULL, 1),
(1855632, 254568, 39850, '<td valign="top">7 - Good idea, colors, composition and textures are good.  Criticism; perhaps a tighter crop at the bottom, to me the bottom ''butts'' that are out of focus dominate the shot, that or different ''focus'', because the ash and tobacco at the ''base'' adds a good element in my opinion.</td>', '7 - Good idea, colors, composition and textures are good.  Criticism; perhaps a tighter crop at the bottom, to me the bottom ''butts'' that are out of focus dominate the shot, that or different ''focus'', because the ash and tobacco at the ''base'' adds a good element in my opinion.', '2005-11-10 16:33:03.000000', NULL, 1),
(1855641, 254902, 39850, '<td valign="top">7 - Good idea.  Criticism; needs ''something'' to bring the potential out more, but no idea how, maybe lighting, angle, not sure.  Different crop perhaps too.</td>', '7 - Good idea.  Criticism; needs ''something'' to bring the potential out more, but no idea how, maybe lighting, angle, not sure.  Different crop perhaps too.', '2005-11-10 16:33:59.000000', NULL, 1),
(1855648, 255245, 39850, '<td valign="top">7 - Good idea and good colors.  Criticism; not much, maybe the crop.  Also if the ant were a little sharper, and perhaps a few more ants (if possible -timing maybe), may have made this even better in my opinion.</td>', '7 - Good idea and good colors.  Criticism; not much, maybe the crop.  Also if the ant were a little sharper, and perhaps a few more ants (if possible -timing maybe), may have made this even better in my opinion.', '2005-11-10 16:34:57.000000', NULL, 1),
(1855654, 255140, 39850, '<td valign="top">7 - Like the idea.  Criticism; the toning is too overdone in my opinion and lessens the effect, or potential effect here.  Maybe an even sharper (side on) angle/perspective.  Different crop too, not sure.</td>', '7 - Like the idea.  Criticism; the toning is too overdone in my opinion and lessens the effect, or potential effect here.  Maybe an even sharper (side on) angle/perspective.  Different crop too, not sure.', '2005-11-10 16:36:14.000000', NULL, 1),
(1855657, 254957, 39850, '<td valign="top">7 - Good idea.  Criticism; difficult with this shot I imagine, but I would like to have seen perhaps a slightly sharper angle/perspective (ground up), and the focus more on the ''fish'', or at least the fish in the bird''s mouth, but difficult as I am sure it was keen to get away.  Of course, the inclusion of the entire wingspan would have made this even better but, this is an obvious opportunity/timing shot and I think you did well to get this as is.</td>', '7 - Good idea.  Criticism; difficult with this shot I imagine, but I would like to have seen perhaps a slightly sharper angle/perspective (ground up), and the focus more on the ''fish'', or at least the fish in the bird''s mouth, but difficult as I am sure it was keen to get away.  Of course, the inclusion of the entire wingspan would have made this even better but, this is an obvious opportunity/timing shot and I think you did well to get this as is.', '2005-11-10 16:38:03.000000', NULL, 1),
(1855660, 255465, 39850, '<td valign="top">7 - Good idea.  Criticism; like to see it even sharper angle/perspective (ground up), and perhaps (if possible) just ''back'' a little more with more of the ground and ''cups'' dominating.</td>', '7 - Good idea.  Criticism; like to see it even sharper angle/perspective (ground up), and perhaps (if possible) just ''back'' a little more with more of the ground and ''cups'' dominating.', '2005-11-10 16:38:53.000000', NULL, 1),
(1855662, 253637, 39850, '<td valign="top">7 - Good idea, nice and simple composition and colors.  Criticism; perhaps a slightly tighter crop on the left, and more banana incorporated on the right, not sure.</td>', '7 - Good idea, nice and simple composition and colors.  Criticism; perhaps a slightly tighter crop on the left, and more banana incorporated on the right, not sure.', '2005-11-10 16:39:31.000000', NULL, 1),
(1855672, 255500, 39850, '<td valign="top">6 - He''s been framed! (no pun intended)</td>', '6 - He''s been framed! (no pun intended)', '2005-11-10 16:41:34.000000', NULL, 1),
(1855683, 255207, 39850, '<td valign="top">6 - Good idea.  Criticism; difficult, but perhaps a little more defintion and ''contrast''.  Some ''minor dust'', etc visible, but otherwise a good concept.  Perhaps, in this instance, some type of frame might have helped, possibly even a different colored background, although not sure on that.</td>', '6 - Good idea.  Criticism; difficult, but perhaps a little more defintion and ''contrast''.  Some ''minor dust'', etc visible, but otherwise a good concept.  Perhaps, in this instance, some type of frame might have helped, possibly even a different colored background, although not sure on that.', '2005-11-10 16:44:52.000000', NULL, 1),
(1855696, 255453, 34659, '<td valign="top">Beautiful representation.  Emotional and powerful.  Great job.  10  (The only 10 I gave out in this challenge.)</td>', 'Beautiful representation.  Emotional and powerful.  Great job.  10  (The only 10 I gave out in this challenge.)', '2005-11-10 16:53:08.000000', NULL, 1),
