(1858389, 252962, 43565, '<td valign="top">I think a different angle would have helped, as would cropping out the partial objects on the left.  It seems too busy to me, and  I had to look hard to find the trash.</td>', 'I think a different angle would have helped, as would cropping out the partial objects on the left.  It seems too busy to me, and  I had to look hard to find the trash.', '2005-11-11 14:46:34.000000', NULL, 1),
(1858391, 255034, 43565, '<td valign="top">This is not my favorite kind of shot, but it is well done technically.</td>', 'This is not my favorite kind of shot, but it is well done technically.', '2005-11-11 14:49:03.000000', NULL, 1),
(1858412, 254103, 44172, '<td valign="top">nice image, good laout or crop, very good quality, meets challenge well - good job :)</td>', 'nice image, good laout or crop, very good quality, meets challenge well - good job :)', '2005-11-11 15:08:36.000000', NULL, 1),
(1858415, 255043, 44172, '<td valign="top">very nice image, like the coloring and layout, a very original idea for meeting this challenge - good work :)</td>', 'very nice image, like the coloring and layout, a very original idea for meeting this challenge - good work :)', '2005-11-11 15:09:40.000000', NULL, 1),
(1858422, 254617, 44172, '<td valign="top">great coloring and smoothness, good layout or crop also - meets challenge well - good work :)</td>', 'great coloring and smoothness, good layout or crop also - meets challenge well - good work :)', '2005-11-11 15:13:01.000000', NULL, 1),
(1858424, 254607, 43565, '<td valign="top">I wish the details of the pile could be seen better, especially at the top.</td>', 'I wish the details of the pile could be seen better, especially at the top.', '2005-11-11 15:14:52.000000', NULL, 1),
(1858430, 255447, 44172, '<td valign="top">very nice composition and layout, wonder what this would look like with black and white, meets challenge well - good work :)</td>', 'very nice composition and layout, wonder what this would look like with black and white, meets challenge well - good work :)', '2005-11-11 15:16:47.000000', NULL, 1),
