INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1858449, 253824, 43565, '<td valign="top">This doesn''t look like garbage--I''m not sure what it is.</td>', 'This doesn''t look like garbage--I''m not sure what it is.', '2005-11-11 15:25:02.000000', NULL, 1),
(1858458, 252777, 43565, '<td valign="top">This would hold my interest more if it were not so centered and symmetrical.</td>', 'This would hold my interest more if it were not so centered and symmetrical.', '2005-11-11 15:28:20.000000', NULL, 1),
(1858471, 254587, 43565, '<td valign="top">Interesting idea, but the shine on the floor makes the photo looked rotated instead of like the trash can is floating.  I also think the pieces of trash should be in focus.</td>', 'Interesting idea, but the shine on the floor makes the photo looked rotated instead of like the trash can is floating.  I also think the pieces of trash should be in focus.', '2005-11-11 15:31:58.000000', NULL, 1),
(1858489, 253737, 24212, '<td valign="top">Lots of detail. I like it.</td>', 'Lots of detail. I like it.', '2005-11-11 15:37:16.000000', NULL, 1),
(1858496, 254633, 24212, '<td valign="top">I quite like the randomness of the pile of junk, but perhaps the pulley dominates the centre a bit.</td>', 'I quite like the randomness of the pile of junk, but perhaps the pulley dominates the centre a bit.', '2005-11-11 15:38:22.000000', NULL, 1),
(1858498, 253691, 24212, '<td valign="top">I like the viewpoint you''ve chosen here.</td>', 'I like the viewpoint you''ve chosen here.', '2005-11-11 15:38:47.000000', NULL, 1),
(1858506, 254617, 24212, '<td valign="top">Nice framing. Did you desaturate certain channels to get the colours right? The patch of ground seems totally colourless, which seems a little out of place compared to the colour in the rest of the frame. Nevertheless, I still feel that this is an attractive shot.</td>', 'Nice framing. Did you desaturate certain channels to get the colours right? The patch of ground seems totally colourless, which seems a little out of place compared to the colour in the rest of the frame. Nevertheless, I still feel that this is an attractive shot.', '2005-11-11 15:41:21.000000', NULL, 1),
(1858508, 253995, 43565, '<td valign="top">For me, this does not meet the challenge, which was to take a photo of garbage.</td>', 'For me, this does not meet the challenge, which was to take a photo of garbage.', '2005-11-11 15:41:44.000000', NULL, 1),
(1858512, 254606, 24212, '<td valign="top">To me, the barrow (cart?) could be in the frame a little more.</td>', 'To me, the barrow (cart?) could be in the frame a little more.', '2005-11-11 15:42:18.000000', NULL, 1),
(1858516, 253016, 24212, '<td valign="top">Great concept and well shot. I would prefer, perhaps, to see a little more sharpening applied.</td>', 'Great concept and well shot. I would prefer, perhaps, to see a little more sharpening applied.', '2005-11-11 15:43:40.000000', NULL, 1),
(1858519, 255407, 24212, '<td valign="top">Great colour and detail. The cigarette ends are almost lost among the stones, though.</td>', 'Great colour and detail. The cigarette ends are almost lost among the stones, though.', '2005-11-11 15:44:28.000000', NULL, 1),
(1858523, 255309, 43565, '<td valign="top">I''m not sure how this is garbage.</td>', 'I''m not sure how this is garbage.', '2005-11-11 15:45:18.000000', NULL, 1),
(1858526, 254752, 24212, '<td valign="top">It looks to me as thought the bank is a little too bright, perhaps verging on the overexposed.</td>', 'It looks to me as thought the bank is a little too bright, perhaps verging on the overexposed.', '2005-11-11 15:47:13.000000', NULL, 1),
(1858530, 254267, 24212, '<td valign="top">Great idea. A good amount of detail captured in the plastic and, indeed, in the rest of the frame.I particularly like the lighting on the plastic. It really makes the shot.</td>', 'Great idea. A good amount of detail captured in the plastic and, indeed, in the rest of the frame.I particularly like the lighting on the plastic. It really makes the shot.', '2005-11-11 15:48:43.000000', NULL, 1),
(1858531, 255207, 24212, '<td valign="top">A nice macro, well lit. If I had to nit-pick, I''d point out that there are what appears to be a few dust spots on your sensor.</td>', 'A nice macro, well lit. If I had to nit-pick, I''d point out that there are what appears to be a few dust spots on your sensor.', '2005-11-11 15:49:51.000000', NULL, 1),
(1858537, 254108, 24212, '<td valign="top">I like the way that you''ve used strong lines. The lighting is great.</td>', 'I like the way that you''ve used strong lines. The lighting is great.', '2005-11-11 15:51:15.000000', NULL, 1),
(1858541, 255553, 24212, '<td valign="top">Lots of detail, although I find some of the reflections a little harsh and the label on the right seems to be positioned just ouside your field of focus and is a little blurred. I''d maybe prefer to see all of it in sharp focus.</td>', 'Lots of detail, although I find some of the reflections a little harsh and the label on the right seems to be positioned just ouside your field of focus and is a little blurred. I''d maybe prefer to see all of it in sharp focus.', '2005-11-11 15:53:09.000000', NULL, 1),
(1858543, 254267, 43565, '<td valign="top">I wish they were not silhouettes, and I can''t see any garbage.</td>', 'I wish they were not silhouettes, and I can''t see any garbage.', '2005-11-11 15:53:34.000000', NULL, 1),
(1858544, 255296, 24212, '<td valign="top">Great use of desaturation and the can seems ideally placed within the frame.</td>', 'Great use of desaturation and the can seems ideally placed within the frame.', '2005-11-11 15:54:37.000000', NULL, 1),
(1858548, 255518, 43565, '<td valign="top">I find the letters (or whatever)  and the small area of sky distracting.</td>', 'I find the letters (or whatever)  and the small area of sky distracting.', '2005-11-11 15:55:20.000000', NULL, 1),
(1858550, 255245, 24212, '<td valign="top">Neat idea. It takes a moment to spot the ant. I like that.</td>', 'Neat idea. It takes a moment to spot the ant. I like that.', '2005-11-11 15:55:35.000000', NULL, 1),
(1858553, 253017, 24212, '<td valign="top">I really like this shot. The strong, clean line through the frame compares well with the detail in the rotten wood. The only downside, however, is the weed that has crept in to the left hand side of the frame.</td>', 'I really like this shot. The strong, clean line through the frame compares well with the detail in the rotten wood. The only downside, however, is the weed that has crept in to the left hand side of the frame.', '2005-11-11 15:57:46.000000', NULL, 1),
(1858557, 253995, 24212, '<td valign="top">I''d perhaps like to see the whole of the sign in sharp focus, but then that''s me.</td>', 'I''d perhaps like to see the whole of the sign in sharp focus, but then that''s me.', '2005-11-11 15:58:59.000000', NULL, 1),
(1858560, 255592, 24212, '<td valign="top">This just made me smile. Great detail and composition.</td>', 'This just made me smile. Great detail and composition.', '2005-11-11 15:59:40.000000', NULL, 1),
(1858562, 254004, 24212, '<td valign="top">A good idea, although I feel that there is a little too much foreground. Lovely sunset.</td>', 'A good idea, although I feel that there is a little too much foreground. Lovely sunset.', '2005-11-11 16:00:37.000000', NULL, 1),
(1858563, 253314, 43565, '<td valign="top">I like this, but the child seems to be the focus, and for this challenge I think the garbage should be the subject or at least as prominent as the child.</td>', 'I like this, but the child seems to be the focus, and for this challenge I think the garbage should be the subject or at least as prominent as the child.', '2005-11-11 16:01:50.000000', NULL, 1),
(1858566, 255453, 24212, '<td valign="top">I like the use of the tight DOF. It really forces attention on the discarded doll. To me, the lines of the road seem to imply someone having dropped it and carried on their way.</td>', 'I like the use of the tight DOF. It really forces attention on the discarded doll. To me, the lines of the road seem to imply someone having dropped it and carried on their way.', '2005-11-11 16:02:33.000000', NULL, 1),
(1858568, 254933, 24212, '<td valign="top">I really like the colours of the leaves and the moss, although the piece of wood or bark in the lower left corner is perhaps a little unnecessary.</td>', 'I really like the colours of the leaves and the moss, although the piece of wood or bark in the lower left corner is perhaps a little unnecessary.', '2005-11-11 16:04:04.000000', NULL, 1),
(1858576, 255465, 24212, '<td valign="top">I really like the idea here. It really seems to tell a story.</td>', 'I really like the idea here. It really seems to tell a story.', '2005-11-11 16:06:04.000000', NULL, 1),
(1858578, 255448, 24212, '<td valign="top">I like the juxtaposition of the bright sign and the almost industrial-looking side of the building.</td>', 'I like the juxtaposition of the bright sign and the almost industrial-looking side of the building.', '2005-11-11 16:07:10.000000', NULL, 1),
(1858588, 255493, 24212, '<td valign="top">Great setup with superb lighting. There appear to be fingerprints on the cans, which spoil the effect created by the cleanliness of the lines, I feel.</td>', 'Great setup with superb lighting. There appear to be fingerprints on the cans, which spoil the effect created by the cleanliness of the lines, I feel.', '2005-11-11 16:11:43.000000', NULL, 1),
(1858593, 254538, 24212, '<td valign="top">I like the stillness of the water, although the band of out-of-focus leaves at the bottom of the frame looks to be a bit out of place.</td>', 'I like the stillness of the water, although the band of out-of-focus leaves at the bottom of the frame looks to be a bit out of place.', '2005-11-11 16:14:14.000000', NULL, 1),
(1858611, 255501, 43400, '<td valign="top">good composition and sky-just a bit dark on the "garbage". Nice DOF and angle too.</td>', 'good composition and sky-just a bit dark on the "garbage". Nice DOF and angle too.', '2005-11-11 16:24:34.000000', NULL, 1),
(1858617, 255483, 43400, '<td valign="top">clever, creativer and witty-- i like it</td>', 'clever, creativer and witty-- i like it', '2005-11-11 16:26:19.000000', NULL, 1),
(1858639, 255114, 44172, '<td valign="top">aww good one! we have a hige squirrel problem with our garbage and I thought of trying to capture that but just didn''t have the time to execute - this is a great image - very original - nice to see something other than garbage in the image - nice work :)</td>', 'aww good one! we have a hige squirrel problem with our garbage and I thought of trying to capture that but just didn''t have the time to execute - this is a great image - very original - nice to see something other than garbage in the image - nice work :)', '2005-11-11 16:35:53.000000', NULL, 1),
(1858645, 255614, 24013, '<td valign="top">YUCKEEEEE!  who wants to see that.  but it''s really well photographed!</td>', 'YUCKEEEEE!  who wants to see that.  but it''s really well photographed!', '2005-11-11 16:37:55.000000', NULL, 1),
(1858646, 255552, 44172, '<td valign="top">I love the editing on this - kind of very moody, I think you might be trying to make a statement or tell a story or something (it''s over my head though - sorry!) but the smoothness of the girl and the coloring is superb - wish I could do this - nice work :)</td>', 'I love the editing on this - kind of very moody, I think you might be trying to make a statement or tell a story or something (it''s over my head though - sorry!) but the smoothness of the girl and the coloring is superb - wish I could do this - nice work :)', '2005-11-11 16:38:22.000000', NULL, 1),
(1858652, 255592, 44172, '<td valign="top">I''d be curious to see this in color - it''s a really nice composition and the quality is top notch - very crisp - good crop - nice work :)</td>', 'I''d be curious to see this in color - it''s a really nice composition and the quality is top notch - very crisp - good crop - nice work :)', '2005-11-11 16:40:04.000000', NULL, 1),
(1858663, 255422, 44172, '<td valign="top">I really like this, it doesn''t have much compositionally but there is something about it, the white wall on the right, next to the red, the green dumpster on the left and the fence falling down in the center - seem to really balance all out really well. Perhaps it''s the editing as I really like the colors and lighting - it fits the challenge and really is a quality image - nice work :)</td>', 'I really like this, it doesn''t have much compositionally but there is something about it, the white wall on the right, next to the red, the green dumpster on the left and the fence falling down in the center - seem to really balance all out really well. Perhaps it''s the editing as I really like the colors and lighting - it fits the challenge and really is a quality image - nice work :)', '2005-11-11 16:43:16.000000', NULL, 1),
(1858671, 255441, 44172, '<td valign="top">good composition - excellent lighting, I want to be able to do something like this  this someday - good work :)</td>', 'good composition - excellent lighting, I want to be able to do something like this  this someday - good work :)', '2005-11-11 16:44:52.000000', NULL, 1),
(1858677, 255500, 44172, '<td valign="top">awww bad doggie - such a great idea and I don''t think there are any others like it in this challenge, good job making an image about something more than just "garbage" - and it still fits the challenge really well - nice work :)</td>', 'awww bad doggie - such a great idea and I don''t think there are any others like it in this challenge, good job making an image about something more than just "garbage" - and it still fits the challenge really well - nice work :)', '2005-11-11 16:47:01.000000', NULL, 1),
(1858729, 254903, 37893, '<td valign="top">I don''t understand how this can be garbage when the bottles are still full?</td>', 'I don''t understand how this can be garbage when the bottles are still full?', '2005-11-11 17:20:00.000000', NULL, 1),
(1858749, 254633, 38725, '<td valign="top">Nice shot, like the desat.</td>', 'Nice shot, like the desat.', '2005-11-11 17:36:23.000000', NULL, 1),
(1858751, 253637, 38725, '<td valign="top">Nice comedic (is that a word?) value.. ;-)</td>', 'Nice comedic (is that a word?) value.. ;-)', '2005-11-11 17:37:16.000000', NULL, 1),
(1858755, 254841, 38725, '<td valign="top">Great shot, like the colours.</td>', 'Great shot, like the colours.', '2005-11-11 17:40:09.000000', NULL, 1),
