(1862251, 253574, 36832, '<td valign="top">How did you get an apple that big?  :)  I like "swish" effect of the apple.  Good luck!</td>', 'How did you get an apple that big?  :)  I like "swish" effect of the apple.  Good luck!', '2005-11-13 14:05:27.000000', NULL, 1),
(1862253, 254830, 36832, '<td valign="top">I really like this one, and I''m not even a coke fan. :)  Nice color and comp.</td>', 'I really like this one, and I''m not even a coke fan. :)  Nice color and comp.', '2005-11-13 14:06:12.000000', NULL, 1),
(1862257, 255140, 36832, '<td valign="top">I think the post-processing is what makes this really unique and memorable.  It''s almost creepy...like a graveyard for automobiles. :)  Nice job and good luck.</td>', 'I think the post-processing is what makes this really unique and memorable.  It''s almost creepy...like a graveyard for automobiles. :)  Nice job and good luck.', '2005-11-13 14:09:13.000000', NULL, 1),
(1862259, 255270, 36832, '<td valign="top">It''s a great shot--clean and crisp.  Well done.  Good luck.</td>', 'It''s a great shot--clean and crisp.  Well done.  Good luck.', '2005-11-13 14:10:33.000000', NULL, 1),
(1862267, 255483, 36832, '<td valign="top">Unique and well-done.  The only "criticism" I have is that I see a lot of small white dots surrounding the "thought bubbles."  It would be great if those were darkened.  Very nice job and very original.</td>', 'Unique and well-done.  The only "criticism" I have is that I see a lot of small white dots surrounding the "thought bubbles."  It would be great if those were darkened.  Very nice job and very original.', '2005-11-13 14:13:27.000000', NULL, 1),
(1862299, 254164, 45596, '<td valign="top">I didn''t care for the photo, but I appreciated the humorous title.</td>', 'I didn''t care for the photo, but I appreciated the humorous title.', '2005-11-13 14:38:53.000000', NULL, 1),
