INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1866571, 253352, 39919, '<td valign="top">This looks almost to "clean" to be garbage...but clearly it is.</td>', 'This looks almost to "clean" to be garbage...but clearly it is.', '2005-11-14 20:56:44.000000', NULL, 1),
(1866580, 254399, 39919, '<td valign="top">The tilt doesn''t work for me.</td>', 'The tilt doesn''t work for me.', '2005-11-14 20:58:26.000000', NULL, 1),
(1866588, 255226, 39919, '<td valign="top">Too much noise for my taste.</td>', 'Too much noise for my taste.', '2005-11-14 20:59:31.000000', NULL, 1),
(1866597, 254004, 39919, '<td valign="top">Nice-ish sunset, but the garbage bin is incidental to the photo, not the subject.</td>', 'Nice-ish sunset, but the garbage bin is incidental to the photo, not the subject.', '2005-11-14 21:01:33.000000', NULL, 1),
(1866605, 253995, 39919, '<td valign="top">Not enough focus, or if you were going to focus on only one word, it would have worked better for me if it had been junk rather than mail.</td>', 'Not enough focus, or if you were going to focus on only one word, it would have worked better for me if it had been junk rather than mail.', '2005-11-14 21:02:54.000000', NULL, 1),
(1866614, 255244, 39919, '<td valign="top">I would be interested in seeing this in color.</td>', 'I would be interested in seeing this in color.', '2005-11-14 21:04:03.000000', NULL, 1),
(1866619, 255303, 39919, '<td valign="top">Your post processing makes it hard for me to tell what this is.</td>', 'Your post processing makes it hard for me to tell what this is.', '2005-11-14 21:05:05.000000', NULL, 1),
(1866623, 255157, 39919, '<td valign="top">A little over exposed.</td>', 'A little over exposed.', '2005-11-14 21:06:09.000000', NULL, 1),
