(1866941, 253637, 46330, '<td valign="top">Great perspective and DOF.  The off center placement of the peel also adds to the tension of the shot.</td>', 'Great perspective and DOF.  The off center placement of the peel also adds to the tension of the shot.', '2005-11-14 22:50:01.000000', NULL, 1),
(1866945, 255594, 46330, '<td valign="top">Excellent use of contrasting colors.</td>', 'Excellent use of contrasting colors.', '2005-11-14 22:51:22.000000', NULL, 1),
(1866961, 255590, 25976, '<td valign="top">Is this a boy or a girl? My grandma and I disagreed. I think its a boy, while my grandma thinks its a girl.</td>', 'Is this a boy or a girl? My grandma and I disagreed. I think its a boy, while my grandma thinks its a girl.', '2005-11-14 22:57:05.000000', NULL, 1),
(1867091, 255114, 33400, '<td valign="top">Good catch, well focused.  This was a difficult challenge to make interesting. Nice job.</td>', 'Good catch, well focused.  This was a difficult challenge to make interesting. Nice job.', '2005-11-14 23:46:10.000000', NULL, 1),
(1867092, 254617, 33400, '<td valign="top">The colors and relection here are wonderful.  Very soulful - especially for garbage. Nice job.</td>', 'The colors and relection here are wonderful.  Very soulful - especially for garbage. Nice job.', '2005-11-14 23:47:07.000000', NULL, 1),
(1867094, 255537, 33400, '<td valign="top">This captures the essence of Garbage.  And you did it with color and style. I like it very much - ought to be in the top three.</td>', 'This captures the essence of Garbage.  And you did it with color and style. I like it very much - ought to be in the top three.', '2005-11-14 23:48:51.000000', NULL, 1),
